<?php require __DIR__.'/lib/bootstrap.php';
if(current_user()) redirect('painel.php');
$error='';
$niches=['Manicure & Pedicure','Lash Designer','Designer de Sobrancelha','Nail Designer','Depilação','Maquiagem','Cabeleireira','Estética Facial'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['whatsapp']??'');$password=$_POST['password']??'';$niche=$_POST['niche']??$niches[0];
 if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8||!in_array($niche,$niches,true))$error='Confira os dados. A senha precisa ter pelo menos 8 caracteres.';
 else try{$slug=slugify($name);$base=$slug;$i=2;while(true){$q=db()->prepare('SELECT id FROM users WHERE slug=?');$q->execute([$slug]);if(!$q->fetch())break;$slug=$base.'-'.$i++;}$q=db()->prepare('INSERT INTO users(name,email,whatsapp,password_hash,slug,niche) VALUES(?,?,?,?,?,?)');$q->execute([$name,$email,$phone,password_hash($password,PASSWORD_DEFAULT),$slug,$niche]);$id=(int)db()->lastInsertId();$q=db()->prepare('INSERT INTO preferences(user_id) VALUES(?)');$q->execute([$id]);session_regenerate_id(true);$_SESSION['user_id']=$id;redirect('perfil.php');}catch(Throwable $e){$error=str_contains($e->getMessage(),'Duplicate')?'Este e-mail já possui cadastro.':'Não foi possível criar a conta. Verifique a configuração do banco de dados.';}
}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Criar conta — Fempro</title><link rel="stylesheet" href="assets/css/app.css"></head><body><div class="auth-wrap"><section class="auth-panel"><a class="logo" href="index.php"><img src="../src/assets/fempro-logo.png" alt="Fempro"></a><form class="auth-form" method="post"><h1 class="h1">Crie sua conta grátis</h1><p class="muted">É rápido, gratuito e fácil de usar.</p><?php if($error): ?><div class="notice"><?= e($error) ?></div><?php endif; ?><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><div class="field"><label>Seu nome</label><input name="name" placeholder="Ana Beatriz" required value="<?= e($_POST['name']??'') ?>"></div><div class="field"><label>WhatsApp</label><input name="whatsapp" type="tel" placeholder="(11) 99999-9999" required></div><div class="field"><label>E-mail</label><input name="email" type="email" placeholder="voce@email.com" required></div><div class="field"><label>Senha</label><input name="password" type="password" minlength="8" placeholder="Mínimo 8 caracteres" required></div><div class="field"><label>Especialidade</label><select name="niche"><?php foreach($niches as $n): ?><option><?= e($n) ?></option><?php endforeach; ?></select></div><button class="btn" style="width:100%">Criar minha conta</button><p class="muted" style="text-align:center;margin-top:20px">Já tem conta? <a href="entrar.php" style="color:var(--pink);font-weight:800">Entrar</a></p></form></section><aside class="auth-photo"><div>Seu talento merece uma agenda profissional.</div></aside></div></body></html>
